'use strict';

// Server-owned deterministic eight-hour field, dealt on Grok's realm map (v1226, Phil 30 Oct 2026: "put this map in game. Swap out the
// old one" / "Make sure we remove all traces of the old map"). Land only - never the sea, never the World Tree island (the void).
// Region nodes are levels 1-6 (6 on the last 4 (220-grid) squares before the coast = "near the end of the region", Phil 3 Oct), wild nodes on the
// islets 7-10 (7 on islet land within 8 cells of a home region). Cells come from ../world-realm.js (GENERATED by tools/realm/build_realm.py).
const REALM=require('../world-realm.js'), GEO=REALM.GEO;
// v1227: the grid is REALM.META.cols x rows (1000 x 596); a mine keeps its world size - one 220-grid square, GEO.FOOT x FOOT cells.
// A node's gx,gy is its top-left cell and x,y (world-percent) the corner its cells share; nodes never overlap one another.
const EPOCH_MS=8*3600000, COUNT=240, GRID_COLS=GEO.COLS, GRID_ROWS=GEO.ROWS, GRID_CELL=GEO.CELL, FOOT=GEO.FOOT;
const RESOURCES=['iron','crystal','silver','coal'];
const MAX_LEVEL=10;   // highest level field() deals (wild 7-10); assets/ui/world-mine-sync.js validates against the same number
const TERRAIN_BLOCKED=new Set(require('./world-terrain-blocked.json').cells);
// 4 and 8 squares of the 220 grid (8 = the old wild corridor's region-edge band), in cells of this grid
const SQ=REALM.META.oldSquareCells, COAST_BAND=Math.round(4*SQ), NEAR_REGION=Math.round(8*SQ);
const REGION_KEYS=['crystor','draymon','tefron','alumron'];
function epochAt(now){ return Math.floor(now/EPOCH_MS); }
function mineRand(seed){ let s=(seed>>>0)||1; return ()=>{ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }
function bfs(seed){   // cell distance (4-neighbour steps) from every seed cell
  const d=new Int32Array(GRID_COLS*GRID_ROWS).fill(-1),q=new Int32Array(GRID_COLS*GRID_ROWS); let tail=0;
  for(let i=0;i<d.length;i++) if(seed(i%GRID_COLS,Math.floor(i/GRID_COLS))){d[i]=0;q[tail++]=i;}
  for(let h=0;h<tail;h++){const i=q[h],x=i%GRID_COLS,y=(i-x)/GRID_COLS;
    for(const [nx,ny] of [[x+1,y],[x-1,y],[x,y+1],[x,y-1]]) if(nx>=0&&ny>=0&&nx<GRID_COLS&&ny<GRID_ROWS&&d[ny*GRID_COLS+nx]<0){d[ny*GRID_COLS+nx]=d[i]+1;q[tail++]=ny*GRID_COLS+nx;}}
  return d;
}
let _cells=null;
// every mine square: FOOT x FOOT cells of one zone's land (never the World Tree island, never a blocked or city cell)
function eligibleCells(){
  if(_cells) return _cells;
  const toSea=bfs((x,y)=>!REALM.isLand(x,y)), toRegion=bfs((x,y)=>REGION_KEYS.includes(REALM.landZone(x,y)));
  const out=[];
  for(let gy=1;gy<GRID_ROWS-FOOT;gy++) for(let gx=1;gx<GRID_COLS-FOOT;gx++){
    const zone=REALM.landZone(gx,gy);
    if(!zone||zone==='worldtree') continue;
    let ok=true;
    for(let j=0;j<FOOT&&ok;j++) for(let i=0;i<FOOT&&ok;i++){ const cx=gx+i,cy=gy+j;
      if(REALM.landZone(cx,cy)!==zone||TERRAIN_BLOCKED.has(cx+','+cy)) ok=false; }
    if(!ok) continue;
    let coast=Infinity,near=Infinity;
    for(let j=0;j<FOOT;j++) for(let i=0;i<FOOT;i++){ const k=(gy+j)*GRID_COLS+gx+i; coast=Math.min(coast,toSea[k]); near=Math.min(near,toRegion[k]); }
    out.push({gx,gy,zone,region:REGION_KEYS.includes(zone),coast,near});
  }
  return _cells=out;
}
function field(epoch){
  const cells=eligibleCells(),out=[],occupied=new Set(),rnd=mineRand((epoch*2654435761)>>>0); let guard=0;
  while(out.length<COUNT&&guard++<COUNT*12){
    const c=cells[Math.floor(rnd()*cells.length)], square=GEO.footCells(c.gx,c.gy).map(p=>p[0]+','+p[1]);
    if(square.some(k=>occupied.has(k))) continue;
    for(const k of square) occupied.add(k);
    let level; const r=rnd();
    if(c.region) level=c.coast<=COAST_BAND?6:(r<0.30?1:r<0.55?2:r<0.75?3:r<0.90?4:5);
    else level=c.near<=NEAR_REGION?7:(r<0.4?8:r<0.75?9:10);
    const res=RESOURCES[Math.floor(rnd()*RESOURCES.length)];
    out.push({id:'mn'+epoch+'_'+out.length,res,level,gx:c.gx,gy:c.gy,x:GEO.cornerX(c.gx),y:GEO.cornerY(c.gy),region:c.zone});
  }
  return out;
}
function nodeById(id,now){
  const ep=epochAt(now), prefix='mn'+ep+'_';
  if(typeof id!=='string'||!id.startsWith(prefix)) return null;
  const index=Number(id.slice(prefix.length));
  if(!Number.isInteger(index)||index<0||index>=COUNT||id!==prefix+index) return null;
  return field(ep)[index]||null;
}
module.exports={EPOCH_MS,COUNT,GRID_COLS,GRID_ROWS,GRID_CELL,FOOT,COAST_BAND,NEAR_REGION,RESOURCES,MAX_LEVEL,epochAt,mineRand,field,nodeById};
